import{_ as a,o as r,c as d,a3 as o}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"路线图","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1791133906000}'),e={name:"roadmap.md"};function h(n,t,l,i,s,c){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="路线图" tabindex="-1">路线图 <a class="header-anchor" href="#路线图" aria-label="Permalink to &quot;路线图&quot;">​</a></h1><p>这一页记录**「有人建议过、但当前版本没做」**的功能：为什么现在不做、要做什么前置、可选方案与风险。</p><p>写下来是为了以后真要动的时候不用从零想，也避免反复讨论同一件事。</p><p>图例：✅ 已完成 · ⏸ 暂缓（有理由）· ❌ 明确不做</p><hr><h2 id="⏸-harmony-迁移-——-建议-不迁移" tabindex="-1">⏸ Harmony 迁移 —— 建议：不迁移 <a class="header-anchor" href="#⏸-harmony-迁移-——-建议-不迁移" aria-label="Permalink to &quot;⏸ Harmony 迁移 —— 建议：不迁移&quot;">​</a></h2><h3 id="建议内容" tabindex="-1">建议内容 <a class="header-anchor" href="#建议内容" aria-label="Permalink to &quot;建议内容&quot;">​</a></h3><p>把当前「反编译源码里直接挂钩」的做法，改成用 Harmony（运行时 IL 织入）打补丁。好处是不用维护反编译源码。</p><h3 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h3><p>本工程<strong>不是</strong>靠运行时织入，而是<strong>重编译整个 <code>Assembly-CSharp.dll</code></strong>：把游戏 DLL 反编译成 C# 源码，在里面直接改调用点，再整体编译回去。</p><h3 id="为什么现在不做" tabindex="-1">为什么现在不做 <a class="header-anchor" href="#为什么现在不做" aria-label="Permalink to &quot;为什么现在不做&quot;">​</a></h3><table tabindex="0"><thead><tr><th>理由</th><th>说明</th></tr></thead><tbody><tr><td>引入新依赖</td><td>Harmony 要额外打包 <code>0Harmony.dll</code>（数百 KB）进 APK</td></tr><tr><td><strong>老 Mono 上风险高</strong></td><td>目标运行时是 Unity <strong>4.7</strong>（2015 年）的 Mono；Harmony 2.x 的 <code>Detour</code> 在这上面兼容性未验证，一旦不兼容是<strong>启动即崩</strong>，崩了连日志都拿不到</td></tr><tr><td>现有方案更可控</td><td>重编译能拿到<strong>编译期报错</strong>（挂钩名写错就编译不过），比运行时静默失败好排查</td></tr><tr><td>收益有限</td><td>我们本来就能改任何地方，Harmony 的主要优势用不上</td></tr></tbody></table><h3 id="若要重开" tabindex="-1">若要重开 <a class="header-anchor" href="#若要重开" aria-label="Permalink to &quot;若要重开&quot;">​</a></h3><ul><li><strong>方案 A（不推荐）</strong>：引入 Harmony 2.x + MonoMod，先用最小 Demo APK 在真机验证 <code>Detour</code> 不崩，再逐步迁移。前置：真机 + 至少 1 周验证期。</li><li><strong>方案 B（推荐替代）</strong>：维持源码内挂钩，但把挂钩点<strong>集中到一个 <code>TuningHooks</code> 门面类</strong>（部分已做）。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p><strong>暂不迁移</strong>。除非将来出现「无法重编译、只能挂原始 DLL」的硬需求才重新评估。</p><hr><h2 id="✅-mod-浏览器-社区仓库-——-已落地-v2-18" tabindex="-1">✅ Mod 浏览器 / 社区仓库 —— 已落地（v2.18） <a class="header-anchor" href="#✅-mod-浏览器-社区仓库-——-已落地-v2-18" aria-label="Permalink to &quot;✅ Mod 浏览器 / 社区仓库 —— 已落地（v2.18）&quot;">​</a></h2><h3 id="建议内容-1" tabindex="-1">建议内容 <a class="header-anchor" href="#建议内容-1" aria-label="Permalink to &quot;建议内容&quot;">​</a></h3><p>游戏内做一个「Mod 市场」：能浏览、下载、安装别人的 Mod。</p><h3 id="最终做法" tabindex="-1">最终做法 <a class="header-anchor" href="#最终做法" aria-label="Permalink to &quot;最终做法&quot;">​</a></h3><p><strong>没有在游戏内加联网，而是在服务器上架了一个网页版仓库。</strong></p><ul><li>游戏内加网络栈要引入 HTTP 客户端 + TLS + 超时重试，老 Mono 上风险高 —— 不做</li><li>改成「<strong>网页浏览 + 分享码导入</strong>」：<code>https://atlanticfleet.asia/mods/</code>，<strong>游戏侧零改动</strong></li><li>网页还带<strong>分享码解析器</strong>：拿到陌生分享码，粘进网页就知道是什么</li></ul><h3 id="仍留待后续-需外部条件" tabindex="-1">仍留待后续（需外部条件） <a class="header-anchor" href="#仍留待后续-需外部条件" aria-label="Permalink to &quot;仍留待后续（需外部条件）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>为什么不做</th></tr></thead><tbody><tr><td>游戏内直接浏览</td><td>需给游戏加网络栈（老 Mono 风险高），暂不做</td></tr><tr><td>用户自助上传 + 审核</td><td>需服务端程序 + 审核机制，当前「作者本地发布」够用</td></tr><tr><td>真实下载计数</td><td>nginx 纯静态拿不到真实下载数，索引里是占位值</td></tr></tbody></table><hr><h2 id="⏸-真机兼容矩阵-——-本机做不了" tabindex="-1">⏸ 真机兼容矩阵 —— 本机做不了 <a class="header-anchor" href="#⏸-真机兼容矩阵-——-本机做不了" aria-label="Permalink to &quot;⏸ 真机兼容矩阵 —— 本机做不了&quot;">​</a></h2><h3 id="建议内容-2" tabindex="-1">建议内容 <a class="header-anchor" href="#建议内容-2" aria-label="Permalink to &quot;建议内容&quot;">​</a></h3><p>维护一张「哪些手机/系统版本能正常玩」的兼容性矩阵。</p><h3 id="现状-1" tabindex="-1">现状 <a class="header-anchor" href="#现状-1" aria-label="Permalink to &quot;现状&quot;">​</a></h3><p>本机<strong>没有安卓模拟器、没有真机</strong>（模拟器方案因内存 / 安全策略受阻，已确认不可行）。所有真机交互（悬浮窗手感、触屏点击、高分屏字号、剪贴板、存档写盘）只能由作者在真机上复测。</p><h3 id="为什么不能直接产出" tabindex="-1">为什么不能直接产出 <a class="header-anchor" href="#为什么不能直接产出" aria-label="Permalink to &quot;为什么不能直接产出&quot;">​</a></h3><p>兼容性矩阵的本质是「<strong>多台真实设备 × 多版本系统</strong> 的实测记录」，必须真机跑出来。本机没有任何一台安卓设备，无法凭空生成。</p><h3 id="替代方案-已做" tabindex="-1">替代方案（已做） <a class="header-anchor" href="#替代方案-已做" aria-label="Permalink to &quot;替代方案（已做）&quot;">​</a></h3><p>把「矩阵」转化为<strong>可操作的流程</strong>：</p><ol><li><strong>游戏内设备自检</strong>：屏幕宽高 / DPI / 系统版本 / 总内存 / 渲染分辨率写进「日志」页，一键导出</li><li><strong>回传模板</strong>：作者测完把日志 + 主观体验（悬浮窗好不好点、字号清不清）贴回，逐台累积</li><li><strong>已知问题清单</strong>：已确认的设备相关问题记在 <a href="/AtlanticFleetSite/docs/changelog">更新日志</a> 里</li></ol><h3 id="待填表格" tabindex="-1">待填表格 <a class="header-anchor" href="#待填表格" aria-label="Permalink to &quot;待填表格&quot;">​</a></h3><table tabindex="0"><thead><tr><th>设备</th><th>系统</th><th>分辨率</th><th>悬浮窗</th><th>触屏点击</th><th>存档写盘</th><th>备注</th></tr></thead><tbody><tr><td>（待作者真机填入）</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="已完成清单" tabindex="-1">已完成清单 <a class="header-anchor" href="#已完成清单" aria-label="Permalink to &quot;已完成清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>版本</th></tr></thead><tbody><tr><td>✅ 游戏内 Mod 控制台「小u」</td><td>v2.0</td></tr><tr><td>✅ Mod 管理中心（禁用/分享/删除/日志）</td><td>v2.1</td></tr><tr><td>✅ 悬浮窗倍速快捷键</td><td>v2.2</td></tr><tr><td>✅ 引擎异常桥接 + 状态页探针</td><td>v2.4 / v2.5</td></tr><tr><td>✅ 倍速不跨重启 + 偏离清单</td><td>v2.7</td></tr><tr><td>✅ 日志落盘 + 一键预设</td><td>v2.9</td></tr><tr><td>✅ 游戏内「帮助」页</td><td>v2.10</td></tr><tr><td>✅ Mod 元信息 + 重名冲突检测</td><td>v2.14</td></tr><tr><td>✅ 日志分级 + 筛选</td><td>v2.15</td></tr><tr><td>✅ 参数键覆盖冲突检测</td><td>v2.16</td></tr><tr><td>✅ 存档编辑页 + 自制模型检查</td><td>v2.17</td></tr><tr><td>✅ 服务器版 Mod 仓库网页</td><td>v2.18</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>版本历史 → <a href="/AtlanticFleetSite/docs/changelog">更新日志</a></li><li>技术细节 → <a href="/AtlanticFleetSite/docs/technical">技术细节</a></li><li>参与贡献 → <a href="/AtlanticFleetSite/docs/dev/contributing">贡献与规范</a></li></ul>',43)])])}const g=a(e,[["render",h]]);export{u as __pageData,g as default};
